/// A sidebar of kit items for the layouts.
macro_rules! sidebar {
    () => {
        r#"<div layer-name="Sidebar" style="display:flex;flex-direction:column;gap:4px;width:256px;padding:16px;border-right:1px solid var(--border);background:var(--card)"><span layer-name="Product" style="padding:8px;font-size:16px;font-weight:700;color:var(--foreground)">Acme</span><x-paper-instance component="Sidebar / Item Active"/><x-paper-instance component="Sidebar / Item" overrides='{"Label":"Projects"}'/><x-paper-instance component="Sidebar / Item" overrides='{"Label":"Team"}'/><x-paper-instance component="Sidebar / Item" overrides='{"Label":"Settings"}'/></div>"#
    };
}

/// Top bar: breadcrumb, search, account.
macro_rules! topbar {
    () => {
        r#"<div layer-name="Top Bar" style="display:flex;align-items:center;gap:12px;height:56px;padding:0 24px;border-bottom:1px solid var(--border)"><x-paper-instance component="Breadcrumb"/><div layer-name="Spacer" style="flex-grow:1"></div><x-paper-instance component="Search"/><x-paper-instance component="Avatar"/></div>"#
    };
}

